package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	Category string   `json:"category"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Price    float64 `json:"price"`
	Category string `json:"category"`
}

func sanitizeField(field string) string {
	// Only allow alphanumeric and underscore
	var cleaned strings.Builder
	for _, c := range field {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
			cleaned.WriteRune(c)
		}
	}
	return cleaned.String()
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	// Build field list - sanitized
	fieldList := "id, name, price, category"
	if len(req.Fields) > 0 {
		var sanitized []string
		for _, f := range req.Fields {
			s := sanitizeField(f)
			if s != "" {
				sanitized = append(sanitized, s)
			}
		}
		if len(sanitized) > 0 {
			fieldList = strings.Join(sanitized, ", ")
		}
	}

	// Build WHERE clause - category is parameterized but query uses LIKE with user input
	var whereClause string
	var args []interface{}
	argIdx := 1

	if req.Category != "" {
		whereClause = fmt.Sprintf(" WHERE category = $%d", argIdx)
		args = append(args, req.Category)
		argIdx++
	}

	// VULNERABILITY: query term is concatenated directly into SQL
	if req.Query != "" {
		if whereClause == "" {
			whereClause = " WHERE name ILIKE '%" + req.Query + "%'"
		} else {
			whereClause += " AND name ILIKE '%" + req.Query + "%'"
		}
	}

	sqlStmt := fmt.Sprintf("SELECT %s FROM products%s ORDER BY id LIMIT %d",
		fieldList, whereClause, req.Limit)

	log.Printf("Executing query: %s with args: %v", sqlStmt, args)

	rows, err := db.Query(sqlStmt, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		pointers := make([]interface{}, len(cols))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
